package com.example.ancapp.data

import dev.ohs.fhir.engine.FhirEngine
import dev.ohs.fhir.engine.get
import dev.ohs.fhir.engine.search.ReferenceClientParam
import dev.ohs.fhir.engine.search.TokenClientParam
import dev.ohs.fhir.engine.search.search
import dev.ohs.fhir.model.r4.Encounter
import dev.ohs.fhir.model.r4.Observation
import dev.ohs.fhir.model.r4.Patient
import dev.ohs.fhir.model.r4.Questionnaire
import dev.ohs.fhir.model.r4.QuestionnaireResponse
import dev.ohs.fhir.model.r4.Resource
import java.time.LocalDate
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.jsonObject

/** Reads and writes the ANC data set held in the local [FhirEngine] database. */
class AncRepository(private val engine: FhirEngine) {

  private val json = Json {
    explicitNulls = false
    encodeDefaults = false
  }

  /**
   * Patients who are currently pregnant, i.e. who have an estimated due date that has not passed,
   * ordered by the soonest due date first.
   */
  suspend fun loadRegister(today: LocalDate = LocalDate.now()): List<PatientSummary> {
    val patients = engine.search<Patient> {}.map { it.resource }
    val dueDates = latestEstimatedDueDates()
    return patients
      .mapNotNull { patient ->
        val id = patient.id ?: return@mapNotNull null
        val dueDate = dueDates[id] ?: return@mapNotNull null
        if (dueDate.isBefore(today)) return@mapNotNull null
        PatientSummary(
          id = id,
          name = patient.name.firstOrNull()?.display().orEmpty().ifBlank { "Unnamed patient" },
          birthDate = patient.birthDate?.value.toLocalDate(),
          estimatedDueDate = dueDate,
        )
      }
      .sortedBy { it.estimatedDueDate }
  }

  suspend fun loadPatient(patientId: String, today: LocalDate = LocalDate.now()): PatientSummary? {
    val patient = runCatching { engine.get<Patient>(patientId) }.getOrNull() ?: return null
    return PatientSummary(
      id = patientId,
      name = patient.name.firstOrNull()?.display().orEmpty().ifBlank { "Unnamed patient" },
      birthDate = patient.birthDate?.value.toLocalDate(),
      estimatedDueDate = latestEstimatedDueDates()[patientId],
    )
  }

  /** The patient's antenatal care contacts, most recent first. */
  suspend fun loadVisits(patientId: String): List<AncVisit> {
    val subject = "Patient/$patientId"
    val encounters =
      engine
        .search<Encounter> { filter(ReferenceClientParam("subject"), { value = subject }) }
        .map { it.resource }
    val observationsByEncounter =
      engine
        .search<Observation> { filter(ReferenceClientParam("subject"), { value = subject }) }
        .map { it.resource }
        .groupBy { it.encounter.targetId() }

    return encounters
      .mapNotNull { encounter ->
        val id = encounter.id ?: return@mapNotNull null
        toVisit(id, encounter.period?.start?.value.toLocalDate(), observationsByEncounter[id].orEmpty())
      }
      .sortedByDescending { it.date ?: LocalDate.MIN }
  }

  /** The ANC contact questionnaire, as the JSON string the Data Capture library expects. */
  suspend fun loadQuestionnaireJson(): String {
    val questionnaire = engine.get<Questionnaire>(Codes.QUESTIONNAIRE_ID)
    val encoded = json.encodeToJsonElement(Questionnaire.serializer(), questionnaire).jsonObject
    // `resourceType` is what tells the Data Capture library which resource it is parsing.
    return json.encodeToString(
      JsonObject.serializer(),
      buildJsonObject {
        put("resourceType", JsonPrimitive("Questionnaire"))
        encoded.forEach { (key, value) -> put(key, value) }
      },
    )
  }

  /** Stores the resources extracted from a completed visit form. */
  suspend fun saveVisit(patientId: String, response: QuestionnaireResponse): List<Resource> {
    val resources = extractAncContact(patientId, response)
    engine.create(*resources.toTypedArray())
    return resources
  }

  private suspend fun latestEstimatedDueDates(): Map<String, LocalDate> =
    engine
      .search<Observation> {
        filter(
          TokenClientParam("code"),
          { value = of(coding(Codes.LOINC, Codes.ESTIMATED_DUE_DATE)) },
        )
      }
      .map { it.resource }
      .mapNotNull { observation ->
        val patientId = observation.subject.targetId() ?: return@mapNotNull null
        val dueDate = observation.dateTimeValue.toLocalDate() ?: return@mapNotNull null
        Triple(patientId, dueDate, observation.effectiveDate ?: LocalDate.MIN)
      }
      // A patient may have been given a revised due date; the most recently recorded one wins.
      .groupBy { it.first }
      .mapValues { (_, entries) -> entries.maxBy { it.third }.second }

  private fun toVisit(
    encounterId: String,
    date: LocalDate?,
    observations: List<Observation>,
  ): AncVisit {
    val bloodPressure = observations.firstOrNull { it.hasLoincCode(Codes.BLOOD_PRESSURE_PANEL) }
    return AncVisit(
      encounterId = encounterId,
      date = date ?: observations.firstNotNullOfOrNull { it.effectiveDate },
      weightKg = observations.firstOrNull { it.hasLoincCode(Codes.BODY_WEIGHT) }?.quantityValue?.asDouble(),
      systolic = bloodPressure?.component(Codes.SYSTOLIC)?.asDouble()?.toInt(),
      diastolic = bloodPressure?.component(Codes.DIASTOLIC)?.asDouble()?.toInt(),
      hemoglobinGDl = observations.firstOrNull { it.hasLoincCode(Codes.HEMOGLOBIN) }?.quantityValue?.asDouble(),
      gestationalAgeWeeks =
        observations.firstOrNull { it.hasLoincCode(Codes.GESTATIONAL_AGE) }?.quantityValue?.asDouble()?.toInt(),
      dangerSigns =
        observations
          .filter { obs -> obs.code.coding.any { it.system?.value == Codes.DANGER_SIGNS } }
          .mapNotNull { obs ->
            obs.codeableConceptValue?.coding?.firstOrNull()?.let { it.display?.value ?: it.code?.value }
          },
      notes = observations.firstOrNull { it.hasLoincCode(Codes.ANNOTATION_COMMENT) }?.stringValue,
    )
  }
}
