@Composable
fun RegisterScreen(
  state: RegisterState,
  onPatientClick: (PatientSummary) -> Unit,
  onRefresh: () -> Unit,
) {
  Scaffold(
    topBar = {
      TopAppBar(
        title = { Text("ANC register") },
        actions = {
          IconButton(onClick = onRefresh, enabled = !state.syncing) {
            Icon(refreshIcon(), contentDescription = "Sync with server")
          }
        },
      )
    },
  ) { padding ->
    Column(Modifier.padding(padding).fillMaxSize()) {
      if (state.syncing) LinearProgressIndicator(Modifier.fillMaxWidth())
      state.message?.let { message ->
        Text(
          text = message,
          style = MaterialTheme.typography.bodySmall,
          color = MaterialTheme.colorScheme.error,
          modifier = Modifier.padding(horizontal = 16.dp, vertical = 8.dp),
        )
      }
      when {
        state.loading -> CenteredProgress()
        state.patients.isEmpty() ->
          EmptyMessage("No pregnant patients on the register yet. Pull from the server to load them.")
        else ->
          LazyColumn(
            contentPadding = PaddingValues(16.dp),
            verticalArrangement = Arrangement.spacedBy(12.dp),
          ) {
            items(state.patients, key = { it.id }) { patient ->
              PatientCard(patient) { onPatientClick(patient) }
            }
          }
      }
    }
  }
}

@Composable
